def cZeroSingleCLM (i : ℕ) : X →L[𝕜] CZeroSum X :=
  LinearMap.mkContinuous
    { toFun := cZeroSingle i
      map_add' := by intro x y; ext n; simp; split_ifs <;> simp
      map_smul' := by intro a x; ext n; simp }
    1 (fun x => by simpa using norm_cZeroSingle_le i x)

